{"content": "def upgrade(record):
    """Convert a v1 record to v2 format. Idempotent for v2 records.
    Never modifies the input.
    """
    # If already v2, return a copy (idempotent)
    if record.get("version") == 2:
        return {"id": record["id"], "title": record["title"], "work_mode": record["work_mode"], "version": 2}

    # v1 -> v2 conversion: make a copy so input is never modified
    new_record = dict(record)

    # name becomes title
    title = new_record.pop("name")

    # remote handling
    remote_val = new_record.pop("remote", None)
    if remote_val == "yes":
        work_mode = "remote"
    elif remote_val == "no":
        work_mode = "office"
    elif remote_val is None:
        # missing remote key -> unknown
        work_mode = "unknown"
    else:
        raise ValueError(f"invalid remote value: {remote_val!r}")

    return {"id": new_record.get("id"), "title": title, "work_mode": work_mode, "version": 2}"}

